SELECT AVG(AvgScrMath), NumTstTakr
FROM satscores
WHERE cds = '1611190130609' AND FundingType = 'Direct';

SELECT ROUND(SUM(CASE WHEN T2.language = 'Simplified Chinese' THEN 1 ELSE 0 END) * 100.0 / COUNT(T1.uuid), 2) AS percentage
FROM cards AS T1
LEFT JOIN foreign_data AS T2 ON T1.uuid = T2.uuid;

SELECT COUNT(*) 
FROM rulings 
WHERE uuid = (SELECT uuid FROM cards WHERE name = 'Mishra''s Factory' ORDER BY multiverseId DESC LIMIT 1);

SELECT COUNT(*) 
FROM cards 
WHERE hasContentWarning = 1 AND availability = 'paper' AND mtgoId IS NULL;

SELECT COUNT(DISTINCT uuid) 
FROM cards 
WHERE frameVersion = '2015' OR frameVersion > '2015' AND text IS NOT NULL;

SELECT ViewCount, LastEditorDisplayName 
FROM posts 
WHERE Title = 'Computer game datasets';

SELECT MIN(Id) 
FROM users 
WHERE DisplayName = 'Michael';

SELECT ROUND(SUM(CASE WHEN T2.member_id IS NULL THEN 1 ELSE 0 END) * 100.0 / COUNT(T1.major_id), 2) AS percentage_no_members
FROM major AS T1
LEFT JOIN member AS T2 ON T1.major_id = T2.link_to_major;

SELECT superhero_name 
FROM superhero 
WHERE height_cm BETWEEN 170 AND 190 AND eye_colour_id IS NULL;

SELECT COUNT(DISTINCT publisher_id) 
FROM superhero 
WHERE height_cm > 200;

SELECT AVG(1999 - strftime('%Y', Birthday)) AS AverageAge
FROM Patient
WHERE ID IN (
    SELECT ID
    FROM Laboratory
    WHERE (
        (IGG IN (3, 4) OR IGA IN (3, 4) OR IGM IN (3, 4))
        OR (U_PRO IN ('300', '1000', 'above'))
    )
);

SELECT MAX(CRP) AS HighestAntiRNP
FROM Laboratory
WHERE CRP < 1.5;
